"""Styles for the beginner lesson, scoped to the tutorials page."""

GUIDE_STYLES = """
.tutorials-page{--lesson-ink:#17263d;--lesson-muted:#607086;--lesson-line:#dce5f2;--lesson-paper:#fff;--lesson-accent:#2457e6;}
.codex-guide [hidden],.tutorials-page [hidden]{display:none!important;}
.lesson-cover{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(270px,1fr);align-items:center;gap:64px;padding:62px 0 48px;border-bottom:1px solid var(--lesson-line);}
.lesson-cover .eyebrow{letter-spacing:.12em;font-size:12px;}
.lesson-cover h1{font-family:'Segoe UI','PingFang SC','Microsoft YaHei',sans-serif;font-size:clamp(42px,5vw,62px);font-weight:650;line-height:1.2;letter-spacing:-.035em;}
.lesson-cover .cover-description{max-width:560px;font-size:17px;line-height:1.85;margin:24px 0;color:#526888;}
.lesson-cover .hero-actions{align-items:center;gap:24px;}
.lesson-cover .cover-meta{font-size:12px;color:var(--lesson-muted);margin:22px 0 0;}
.lesson-demo{background:#152c4c;color:#f0f6ff;border-radius:10px;padding:24px;box-shadow:12px 14px 0 #edf3ff;}
.lesson-demo-bar{display:flex;align-items:center;gap:5px;border-bottom:1px solid #3b557b;padding-bottom:18px;color:#b5c9e7;font-size:12px;}
.lesson-demo-bar i{width:6px;height:6px;border-radius:50%;background:#83a6d9;}.lesson-demo-bar span{margin-left:auto;}
.lesson-demo .demo-command{font:14px/1.8 'SFMono-Regular',Consolas,monospace;color:#d5e6ff;margin:22px 0;}
.lesson-demo .demo-message{margin:0 0 14px;padding:14px;border:1px solid #5677a6;border-radius:5px;font-size:14px;color:#e3efff;}
.lesson-demo .demo-reply{margin:18px 0 0;color:#b8d9ff;font-size:15px;}.lesson-demo small{display:block;color:#aec6e8;font-size:11px;margin-top:24px;}
.lesson-intro-line{display:flex;justify-content:space-between;gap:16px;align-items:center;margin:28px 0 36px;font-size:14px;}.lesson-intro-line p{margin:0;}.lesson-intro-line a{white-space:nowrap;}
.lesson-frame{display:grid;grid-template-columns:222px minmax(0,1fr);gap:38px;align-items:start;}
.lesson-sidebar{position:sticky;top:108px;padding-right:22px;border-right:1px solid var(--lesson-line);}
.lesson-sidebar fieldset{padding:0;margin:0 0 18px;border:0;min-width:0;}.lesson-sidebar legend,.lesson-select-label{display:block;font-size:12px;font-weight:700;color:var(--lesson-muted);margin-bottom:8px;}
.lesson-os-options{display:flex;border:1px solid #c7d2c9;border-radius:5px;padding:3px;background:#fff;}
.lesson-os-options label{flex:1;display:flex;align-items:center;justify-content:center;min-height:40px;gap:6px;font-size:13px;cursor:pointer;border-radius:3px;}
.lesson-os-options label:has(:checked){background:#203e33;color:#fff;}.lesson-os-options input{accent-color:#81b39a;width:14px;height:14px;margin:0;}.lesson-os-options label:focus-within{outline:2px solid var(--lesson-accent);outline-offset:3px;}
.lesson-sidebar select{width:100%;min-height:42px;border:1px solid #bfcac1;border-radius:4px;color:var(--lesson-ink);background:#fff;padding:8px;font:inherit;font-size:13px;}
.lesson-sidebar select:focus-visible,.lesson-mobile-select:focus-visible{outline:2px solid var(--lesson-accent);outline-offset:2px;}
.lesson-sidebar nav{margin:28px 0 20px;}.lesson-sidebar ol{list-style:none;padding:0;margin:0;}.lesson-sidebar li{margin:0;}
.lesson-sidebar nav a{display:flex;align-items:center;gap:12px;min-height:45px;padding:8px 10px;color:#526888;font-size:14px;font-weight:500;border-left:2px solid transparent;}
.lesson-sidebar nav a span{font:12px/1.5 Consolas,monospace;color:#607086;}.lesson-sidebar nav a[aria-current='step']{background:#edf3ff;border-left-color:#2457e6;color:#1844bf;font-weight:700;}.lesson-sidebar nav a[aria-current='step'] span{color:#2457e6;}
.lesson-sidebar .lesson-help-link{display:block;font-size:13px;padding:12px 10px;border-top:1px solid var(--lesson-line);}.lesson-mobile-navigation{display:none;}
.lesson-paper{min-width:0;background:var(--lesson-paper);border:1px solid #dce5f2;border-radius:8px;box-shadow:0 6px 22px #152c4c04;scroll-margin-top:108px;}
.lesson-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:16px 30px;border-bottom:1px solid #dce5f2;font-size:12px;color:var(--lesson-muted);}
.lesson-toolbar button{border:0;background:transparent;color:#30624f;padding:6px 0;cursor:pointer;font:inherit;text-decoration:underline;text-underline-offset:4px;}
.lesson-step{padding:34px 36px 30px;outline:none;}.lesson-step+.lesson-step{border-top:1px solid var(--lesson-line);}
.lesson-step-header{display:grid;grid-template-columns:auto minmax(0,1fr);gap:20px;align-items:start;margin-bottom:26px;}
.lesson-step-number{font:italic 50px/.95 Georgia,serif;color:#92acd3;}.lesson-step-header .eyebrow{font-size:11px;color:var(--lesson-accent);letter-spacing:.08em;margin-bottom:8px;}.lesson-step h2{font-size:28px;font-weight:700;line-height:1.4;margin:0;color:var(--lesson-ink);}
.lesson-step .step-lead{font-size:16px;color:#607086;margin:10px 0 0;}.lesson-step p,.lesson-step li{font-size:15px;line-height:1.85;}.lesson-step p{color:#485d7c;}
.lesson-step h3{font-size:18px;margin:26px 0 12px;}.lesson-step h4{font-size:16px;line-height:1.5;margin:22px 0 10px;}.lesson-step ol{padding-left:22px;}.lesson-step li{padding-left:4px;margin:10px 0;}
.lesson-step .step-settings{font-size:12px;display:none;}.lesson-route-choices{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:0 0 24px;}
.lesson-route-choices button{position:relative;min-height:125px;text-align:left;border:1px solid #c9d3c7;border-radius:6px;background:transparent;padding:20px;cursor:pointer;color:var(--lesson-ink);font:inherit;}
.lesson-route-choices strong{display:block;font-size:18px;font-weight:650;margin:6px 0;}.lesson-route-choices small{display:block;font-size:12px;color:#607086;}.lesson-route-choices button[aria-pressed='true']{background:#eaf0e4;border:2px solid #41634f;padding:19px;}.lesson-route-choices button[aria-pressed='true']:after{content:'已选择';position:absolute;right:12px;top:12px;font-size:10px;color:#42644e;}
.lesson-route-choices button:focus-visible,.lesson-controls a:focus-visible,.lesson-toolbar button:focus-visible{outline:2px solid var(--lesson-accent);outline-offset:3px;}
.guide-platform{margin:18px 0;min-width:0;}.guide-platform-label{font-size:11px!important;letter-spacing:.04em;color:#6d7e72!important;margin:0 0 8px!important;}
.guide-code{margin:12px 0 18px;background:#152c4c;color:#ecf4ff;border-radius:5px;overflow:hidden;}.guide-code-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:8px 14px;font-size:11px;color:#bad0f0;background:#213d65;}
.guide-code pre{margin:0;padding:18px;background:transparent;border-radius:0;white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px;line-height:1.85;color:#ecf4ff;}.guide-code code{overflow-wrap:anywhere;}.guide-code pre:focus-visible{outline:2px solid #cfaa70;outline-offset:-3px;}
.guide-code.is-prompt{background:#f1f6ff;border:1px solid #d4e1f5;}.guide-code.is-prompt .guide-code-heading{background:#e6effe;color:#526888;}.guide-code.is-prompt pre{color:#334e75;}.guide-code.is-prompt .guide-copy{border-color:#b4c9ea;color:#334e75;}
.guide-copy{border:1px solid #748c7a;border-radius:3px;background:transparent;color:#e9f0e9;padding:5px 9px;min-height:32px;font:inherit;cursor:pointer;flex-shrink:0;}.guide-copy:hover{background:#ffffff15;}.guide-copy:focus-visible{outline:2px solid #d6af72;outline-offset:2px;}
.lesson-result{display:flex;align-items:flex-start;gap:12px;margin:26px 0 10px;padding:16px 0;border-top:1px dashed #b2c9e9;}.lesson-result:before{content:'↳';font:26px/1 Georgia,serif;color:#2457e6;}.lesson-result p{margin:0;font-size:14px;color:#405f8c;}.lesson-result strong{display:block;font-size:12px;font-weight:700;margin-bottom:4px;}
.lesson-margin-note{border-left:2px solid #7e9ad4;padding:2px 0 2px 14px;font-size:13px!important;color:#526888!important;margin:20px 0;}
.guide-faq{border-top:1px solid var(--lesson-line);margin-top:18px;}.guide-faq summary{cursor:pointer;padding:15px 0;font-size:14px;line-height:1.6;color:#3e5c85;}.guide-faq[open] summary{font-weight:700;}.guide-faq p{font-size:14px;}.guide-faq summary:focus-visible{outline:2px solid var(--lesson-accent);outline-offset:3px;}
.lesson-controls{display:flex;justify-content:space-between;gap:16px;align-items:center;margin:0 36px;padding:22px 0;border-top:1px solid #dce5f2;font-size:14px;}.lesson-controls a{display:inline-flex;gap:10px;align-items:center;min-height:42px;}.lesson-controls a:last-child{background:#254b3c;border-radius:4px;color:#fff;padding:10px 18px;margin-left:auto;}
.lesson-config-example{margin:20px 0 22px;border:1px solid #c7d8ee;border-radius:6px;padding:20px;background:#f4f8ff;}.lesson-config-example figcaption{font-size:11px;color:#607086;margin-bottom:16px;}.lesson-config-example dl{margin:0;display:grid;grid-template-columns:70px minmax(0,1fr);align-items:center;gap:12px;font-size:13px;}.lesson-config-example dd{margin:0;border:1px solid #c7d8ee;background:#fff;padding:8px 10px;overflow-wrap:anywhere;}.lesson-config-example dt{color:#607086;}
.lesson-folder{display:flex;align-items:center;gap:16px;padding:20px 24px;background:#edf4ff;border-radius:4px;margin:24px 0;}.lesson-folder svg{flex-shrink:0;color:#3863a6;}.lesson-folder p{margin:0;font-size:14px;}.lesson-folder small{display:block;color:#607086;font-size:12px;margin-bottom:5px;}
.lesson-afterword{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;border-top:1px solid var(--lesson-line);padding-top:24px;margin:40px 0;color:var(--lesson-muted);font-size:13px;}.lesson-afterword p{max-width:560px;margin:0;}.lesson-afterword a{white-space:nowrap;}
.lesson-support{display:grid;grid-template-columns:222px minmax(0,1fr);gap:38px;margin-top:64px;border-top:1px solid var(--lesson-line);padding-top:32px;}.lesson-support h2{font:650 30px/1.3 'Segoe UI','PingFang SC','Microsoft YaHei',sans-serif;margin-bottom:12px;}.lesson-support header p{font-size:14px;}.lesson-support .guide-faq:first-child{border-top:0;margin-top:0;}.lesson-support .guide-faq{margin:0;}.lesson-support .guide-faq summary{padding:18px 0;color:#23436c;}.lesson-support .guide-faq p{line-height:1.85;}.lesson-support .guide-faq[open]{padding-bottom:8px;}
.lesson-exercise{margin-top:40px;border:1px solid #c7d8ee;border-radius:6px;background:#f1f6ff;}.lesson-exercise>summary{display:flex;justify-content:space-between;gap:18px;align-items:center;cursor:pointer;padding:26px 30px;list-style:none;}.lesson-exercise>summary::-webkit-details-marker{display:none;}.lesson-exercise>summary:after{content:'＋';font-size:26px;color:#45699b;}.lesson-exercise[open]>summary:after{content:'−';}.lesson-exercise>summary small{display:block;color:#45699b;font-size:12px;margin-bottom:6px;}.lesson-exercise>summary strong{font-size:22px;color:#23436c;font-weight:600;}.lesson-exercise-content{padding:0 30px 30px;max-width:850px;}.lesson-exercise-content h3{margin:26px 0 12px;}.lesson-exercise-content p{font-size:15px;line-height:1.85;}.lesson-exercise>summary:focus-visible{outline:2px solid var(--lesson-accent);outline-offset:3px;}
.lesson-references{margin:30px 0 0;font-size:12px;color:#607086;}.lesson-references summary{cursor:pointer;padding:12px 0;}.lesson-references p{font-size:12px;line-height:1.85;margin:8px 0;}
.lesson-sr-only{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap;}
.lesson-step .step-settings{margin:0 0 10px;font-size:11px;}
.tutorial-supplement{margin-top:40px;border-top:1px solid var(--lesson-line);padding:24px 0;}.tutorial-supplement>summary{cursor:pointer;display:flex;justify-content:space-between;gap:20px;align-items:center;list-style:none;}.tutorial-supplement>summary::-webkit-details-marker{display:none;}.tutorial-supplement>summary:after{content:'＋';font-size:24px;}.tutorial-supplement[open]>summary:after{content:'−';}.tutorial-supplement>summary strong{display:block;color:#23436c;font-size:18px;}.tutorial-supplement>summary span{font-size:13px;color:#607086;}.tutorial-supplement .tutorial-block{background:transparent;border:0;padding:20px 0;}.tutorial-planned{font-size:13px;color:#607086;line-height:1.9;padding:20px 0;border-top:1px solid var(--lesson-line);}.tutorial-planned p{margin:0;}
@media(min-width:901px){.lesson-split{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:28px;}.lesson-split>.lesson-margin-note{align-self:start;margin-top:0;}}
@media(max-width:900px){.lesson-cover{gap:30px;grid-template-columns:minmax(0,1.3fr) minmax(230px,1fr);padding-top:40px;}.lesson-cover h1{font-size:42px;}.lesson-frame{grid-template-columns:1fr;gap:18px;}.lesson-sidebar{position:static;border:0;padding:18px;background:#f1f6ff;border-radius:6px;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px;align-items:end;}.lesson-sidebar fieldset{margin:0;}.lesson-sidebar nav{display:none;}.lesson-sidebar .lesson-help-link{border:0;padding:8px 0;text-align:right;margin:0;align-self:center;}.lesson-mobile-navigation{display:block;}.lesson-step .step-settings{display:inline;}.lesson-support{grid-template-columns:1fr;gap:10px;}.lesson-support header{display:flex;gap:20px;align-items:baseline;}.lesson-support header p{margin:0;}}
@media(max-width:620px){.lesson-cover{grid-template-columns:1fr;padding:36px 0;gap:28px;}.lesson-cover h1{font-size:40px;}.lesson-cover .cover-description{font-size:16px;margin:18px 0;}.lesson-demo{padding:20px;box-shadow:6px 6px 0 #edf3ff;}.lesson-demo .demo-command{margin:14px 0;}.lesson-demo small{margin-top:16px;}.lesson-intro-line{display:block;margin:24px 0;font-size:13px;}.lesson-intro-line a{display:inline-block;margin-top:8px;}.lesson-toolbar{padding:12px 18px;}.lesson-step{padding:24px 20px;}.lesson-step-header{gap:12px;margin-bottom:20px;}.lesson-step-number{font-size:38px;}.lesson-step h2{font-size:24px;}.lesson-step .step-lead{font-size:14px;}.lesson-step p,.lesson-step li{font-size:15px;}.lesson-route-choices{gap:10px;}.lesson-route-choices button{padding:14px 12px;min-height:124px;}.lesson-route-choices button[aria-pressed='true']{padding:13px 11px;}.lesson-route-choices strong{font-size:16px;margin-top:20px;}.lesson-route-choices small{font-size:11px;}.guide-code pre{padding:14px;font-size:12px;}.lesson-config-example{padding:14px;margin:20px 0;}.lesson-config-example dl{grid-template-columns:1fr;gap:7px;}.lesson-config-example dt:not(:first-child){margin-top:8px;}.lesson-controls{margin:0 20px;font-size:13px;}.lesson-controls a:last-child{padding:9px 12px;}.lesson-folder{padding:16px 12px;gap:10px;}.lesson-folder code{font-size:12px;}.lesson-afterword{display:block;margin:30px 0;}.lesson-afterword a{display:inline-block;margin-top:12px;}.lesson-support{margin-top:40px;padding-top:24px;}.lesson-support header{display:block;}.lesson-support h2{font-size:28px;}.lesson-exercise>summary{padding:22px 20px;}.lesson-exercise>summary strong{font-size:19px;}.lesson-exercise-content{padding:0 20px 24px;}.tutorial-supplement>summary strong{font-size:17px;}}
@media print{.lesson-step[hidden],.codex-guide [data-auth][hidden]{display:block!important;}.lesson-sidebar,.lesson-toolbar,.lesson-controls,.guide-copy,.site-header{display:none!important;}.lesson-frame{display:block;}.lesson-paper{border:0;box-shadow:none;}.lesson-step{break-inside:auto;}.lesson-cover{grid-template-columns:1fr;}.lesson-demo{display:none;}}
@media(max-width:620px){.lesson-sidebar .lesson-os-settings,.lesson-sidebar .lesson-help-link{grid-column:1/-1;}.lesson-sidebar .lesson-help-link{text-align:left;padding:0;font-size:12px;}.lesson-step .step-settings{display:block;}.lesson-os-options label{min-width:0;}.lesson-step-header{gap:12px;}}
"""
